inline void reentryStateVector::UnPackTo(reentryStateVectorT *_o, const ::flatbuffers::resolver_function_t *_resolver) const {
  (void)_o;
  (void)_resolver;
  { auto _e = EPOCH(); if (_e) _o->EPOCH = _e->str(); }
  { auto _e = REF_FRAME(); if (_e) _o->REF_FRAME = _e->str(); }
  { auto _e = X(); _o->X = _e; }
  { auto _e = Y(); _o->Y = _e; }
  { auto _e = Z(); _o->Z = _e; }
  { auto _e = X_DOT(); _o->X_DOT = _e; }
  { auto _e = Y_DOT(); _o->Y_DOT = _e; }
  { auto _e = Z_DOT(); _o->Z_DOT = _e; }
}

