inline ::flatbuffers::Offset<reentryStateVector> reentryStateVector::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const reentryStateVectorT* _o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  (void)_rehasher;
  (void)_o;
  struct _VectorArgs { ::flatbuffers::FlatBufferBuilder *__fbb; const reentryStateVectorT* __o; const ::flatbuffers::rehasher_function_t *__rehasher; } _va = { &_fbb, _o, _rehasher}; (void)_va;
  auto _EPOCH = _o->EPOCH.empty() ? 0 : _fbb.CreateString(_o->EPOCH);
  auto _REF_FRAME = _o->REF_FRAME.empty() ? 0 : _fbb.CreateString(_o->REF_FRAME);
  auto _X = _o->X;
  auto _Y = _o->Y;
  auto _Z = _o->Z;
  auto _X_DOT = _o->X_DOT;
  auto _Y_DOT = _o->Y_DOT;
  auto _Z_DOT = _o->Z_DOT;
  return CreatereentryStateVector(
      _fbb,
      _EPOCH,
      _REF_FRAME,
      _X,
      _Y,
      _Z,
      _X_DOT,
      _Y_DOT,
      _Z_DOT);
}

