inline RDMUserDefinedParameterT *RDMUserDefinedParameter::UnPack(const ::flatbuffers::resolver_function_t *_resolver) const {
  auto _o = std::make_unique<RDMUserDefinedParameterT>();
  UnPackTo(_o.get(), _resolver);
  return _o.release();
}

inline void RDMUserDefinedParameter::UnPackTo(RDMUserDefinedParameterT *_o, const ::flatbuffers::resolver_function_t *_resolver) const {
  (void)_o;
  (void)_resolver;
  { auto _e = PARAM_NAME(); if (_e) _o->PARAM_NAME = _e->str(); }
  { auto _e = PARAM_VALUE(); if (_e) _o->PARAM_VALUE = _e->str(); }
}

inline ::flatbuffers::Offset<RDMUserDefinedParameter> CreateRDMUserDefinedParameter(::flatbuffers::FlatBufferBuilder &_fbb, const RDMUserDefinedParameterT *_o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  return RDMUserDefinedParameter::Pack(_fbb, _o, _rehasher);
}

inline ::flatbuffers::Offset<RDMUserDefinedParameter> RDMUserDefinedParameter::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const RDMUserDefinedParameterT* _o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  (void)_rehasher;
  (void)_o;
  struct _VectorArgs { ::flatbuffers::FlatBufferBuilder *__fbb; const RDMUserDefinedParameterT* __o; const ::flatbuffers::rehasher_function_t *__rehasher; } _va = { &_fbb, _o, _rehasher}; (void)_va;
  auto _PARAM_NAME = _o->PARAM_NAME.empty() ? 0 : _fbb.CreateString(_o->PARAM_NAME);
  auto _PARAM_VALUE = _o->PARAM_VALUE.empty() ? 0 : _fbb.CreateString(_o->PARAM_VALUE);
  return CreateRDMUserDefinedParameter(
      _fbb,
      _PARAM_NAME,
      _PARAM_VALUE);
}

inline const RDM *GetRDM(const void *buf) {
  return ::flatbuffers::GetRoot<RDM>(buf);
}

inline const RDM *GetSizePrefixedRDM(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<RDM>(buf);
}

inline const char *RDMIdentifier() {
  return "$RDM";
}

inline bool RDMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, RDMIdentifier());
}

inline bool SizePrefixedRDMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, RDMIdentifier(), true);
}

template <bool B = false>
inline bool VerifyRDMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<RDM>(RDMIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedRDMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<RDM>(RDMIdentifier());
}

inline void FinishRDMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<RDM> root) {
  fbb.Finish(root, RDMIdentifier());
}

inline void FinishSizePrefixedRDMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<RDM> root) {
  fbb.FinishSizePrefixed(root, RDMIdentifier());
}

inline std::unique_ptr<RDMT> UnPackRDM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<RDMT>(GetRDM(buf)->UnPack(res));
}

inline std::unique_ptr<RDMT> UnPackSizePrefixedRDM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<RDMT>(GetSizePrefixedRDM(buf)->UnPack(res));
}

